   [86]={next_id=87, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“在一辆列车上，亚伦如同英雄般登场，帅气的脸庞，挺拔的身姿，迷人的双眼。深深刻进了她的脑海。”", msg_color="", msg_size=0, talker="小说", audio="", img="arts/ui/bg/story/storybg_ACT302_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
